package com.mahesh.empleave.department;import jakarta.persistence.*;import lombok.*;@Entity @Getter @NoArgsConstructor(access=AccessLevel.PROTECTED) public class Department{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(nullable=false,unique=true) private String name;private String code;public Department(String n,String c){name=n;code=c;}public void update(String n,String c){name=n;code=c;}}
